"""
    updates the current maximal number allowed by a factor
    :param m: multiplication factor
    :param init_max: initial maximum chromosome number allowed
    :param max_allowed: previous maximum chromosome number allowed
    :return: the current updated maximum for next iteration
    """
def update_max_for_sim(m: Any, init_max: Any, max_allowed: Any) -> object {
    max_for_sim = (200 * m) + init_max;
    if (max_for_sim < max_allowed) {
        max_for_sim = max_allowed;
    }
    return max_for_sim;
}

"""Get indices of point's neighbors in square matrix of size `size`.

    Unless point (i, j) is on the boundary of the size x size square, this will
    be a list of 4 elements.

    Args:
        size: Int.
        point: Tuple of ints (i, j). Must satisfy 0 <= i, j < size.

    Returns:
        neighbors: List of tuples. Length 2 (if point is a corner), 3 (if point
            is on an edge), or 4 (if point is in the interior).
    """
def _get_neighbors(size: Any, point: Any) -> object {
    (i, j) = point;
    neighbors = [((i - 1), j), ((i + 1), j), (i, (j - 1)), (i, (j + 1))];
    _valid_neighbor = lambda (neighbor: Any) { all(
        (0 <= x < size) for x in neighbor
    ); };
    neighbors = `list(filter(_valid_neighbor, neighbors));
    return neighbors;
}

